//! Unicode blocks that permit a line break without a space, generated from
//! maplibre-native.
//!
//! Source revision: b5a2922844c9
//!
//! Taken from `i18n.cpp`'s own table rather than from Unicode's Blocks.txt: mbgl
//! comments out the blocks it does not consult, and a table built from the standard
//! would include them and break lines where mbgl does not.
//!
//! Generated by `cargo run -p mbgl-codegen`. Do not edit.

/// A Unicode block, inclusive at both ends.
pub type Block = (u32, u32);

/// Every block `allowsIdeographicBreaking` consults, in codepoint order.
pub const IDEOGRAPHIC_BLOCKS: [Block; 20] = [
    // CJKRadicalsSupplement
    (0x2E80, 0x2EFF),
    // KangxiRadicals
    (0x2F00, 0x2FDF),
    // IdeographicDescriptionCharacters
    (0x2FF0, 0x2FFF),
    // CJKSymbolsandPunctuation
    (0x3000, 0x303F),
    // Hiragana
    (0x3040, 0x309F),
    // Katakana
    (0x30A0, 0x30FF),
    // Bopomofo
    (0x3100, 0x312F),
    // BopomofoExtended
    (0x31A0, 0x31BF),
    // CJKStrokes
    (0x31C0, 0x31EF),
    // KatakanaPhoneticExtensions
    (0x31F0, 0x31FF),
    // EnclosedCJKLettersandMonths
    (0x3200, 0x32FF),
    // CJKCompatibility
    (0x3300, 0x33FF),
    // CJKUnifiedIdeographsExtensionA
    (0x3400, 0x4DBF),
    // CJKUnifiedIdeographs
    (0x4E00, 0x9FFF),
    // YiSyllables
    (0xA000, 0xA48F),
    // YiRadicals
    (0xA490, 0xA4CF),
    // CJKCompatibilityIdeographs
    (0xF900, 0xFAFF),
    // VerticalForms
    (0xFE10, 0xFE1F),
    // CJKCompatibilityForms
    (0xFE30, 0xFE4F),
    // HalfwidthandFullwidthForms
    (0xFF00, 0xFFEF),
];
